class _ShellRuntimeCard extends StatelessWidget {
  const _ShellRuntimeCard({required this.item});

  final _ShellRuntimeItem item;

  @override
  Widget build(BuildContext context) {
    final bytes = base64Decode(item.assetBase64);
    return SizedBox(
      width: 260,
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(14),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                item.label + '  ' + item.hex,
                style: Theme.of(context).textTheme.titleMedium,
              ),
              const SizedBox(height: 12),
              Row(
                children: [
                  _RuntimeSample(bytes: bytes, size: 58, dark: false),
                  const SizedBox(width: 10),
                  _RuntimeSample(bytes: bytes, size: 58, dark: true),
                ],
              ),
              const SizedBox(height: 8),
              const Text('58 px · light / dark'),
              const SizedBox(height: 12),
              Center(child: _RuntimeSample(bytes: bytes, size: 96, dark: false)),
              const Center(child: Text('96 px inspection')),
              const SizedBox(height: 12),
              Center(child: _RuntimeSample(bytes: bytes, size: 160, dark: true)),
              const Center(child: Text('160 px reference scale')),
            ],
          ),
        ),
      ),
    );
  }
}

class _RuntimeSample extends StatelessWidget {
  const _RuntimeSample({
    required this.bytes,
    required this.size,
    required this.dark,
  });

  final Uint8List bytes;
  final double size;
  final bool dark;

  @override
  Widget build(BuildContext context) {
    return Container(
      width: size + 20,
      height: size + 20,
      alignment: Alignment.center,
      decoration: BoxDecoration(
        color: dark ? const Color(0xFF171A20) : const Color(0xFFF5F6F8),
        borderRadius: BorderRadius.circular(12),
      ),
      child: Image.memory(
        bytes,
        width: size,
        height: size,
        fit: BoxFit.contain,
        filterQuality: FilterQuality.high,
        gaplessPlayback: true,
      ),
    );
  }
}

